// Two ways in, on purpose:
//  1. a fault POSTed directly in the body (manual demo, testing)
//  2. a bare wake-up from Grafana, where the body carries no usable
//     labels — then Elasticsearch tells us what broke.
// Grafana's label templating rendered '[no value]', so anything that
// looks like that is treated as absent.
//
// trace_id is the important field here. The beacon that first saw the
// fault minted it and it is already on the event in Elasticsearch, so
// the decision made below, the config push that follows, and the commit
// message left on the router all end up under the same id. A fault
// posted by hand has no id yet, so one is minted and marked as such.
const items = $input.all();
const es = items[items.length - 1].json;
const posted = $('Alert webhook').first().json.body || {};

function clean(v) {
  if (v === undefined || v === null) return '';
  const s = String(v).trim();
  return (s === '' || s === '[no value]') ? '' : s;
}

function mintTrace(device) {
  const t = new Date().toISOString().replace(/[-:]/g, '').replace(/\..+/, 'Z');
  const r = Math.random().toString(16).slice(2, 8);
  return `${device || 'manual'}-${t}-${r}`;
}

// 1a. Grafana's own labels, when it sends usable ones.
//
// This path did not exist, and its absence was the reason two faults at
// once behaved badly. The rule's series are named after the FIELD the
// Elasticsearch datasource grouped on -- data.device.keyword, not device
// -- so the short names were always empty and every notification fell
// through to path 2 below, which returns EVERY recent fault as a list.
//
// One notification then processed all of them, and two notifications for
// two different faults each processed the same list. Observed: srl2 got
// two decisions two seconds apart and srl3, whose own alert instance was
// firing at the same moment, got none for five minutes.
//
// An alert is about one fault. Handle that one.
const galerts = (($('Alert webhook').first().json.body || {}).alerts) || [];
const glabels = (galerts[0] || {}).labels || {};
const gdev = clean(glabels['data.device.keyword'] || glabels.device);
const gflt = clean(glabels['data.fault.keyword'] || glabels.fault);
if (gdev && gflt) {
  const gif = clean(glabels['data.interface.keyword'] || glabels.interface);
  // Grafana knows WHICH fault; Elasticsearch knows its trace id and
  // detail. Match on the triple rather than taking the newest event.
  const hits0 = (es.hits && es.hits.hits) || [];
  let match = null;
  for (const h of hits0) {
    const d = h._source.data || {};
    if (clean(d.device) === gdev && clean(d.fault) === gflt &&
        clean(d.interface) === gif) { match = d; break; }
  }
  return [{ json: {
    device: gdev,
    fault: gflt,
    interface: gif,
    detail: clean(match && match.detail),
    peer: clean(match && match.peer),
    trace_id: clean(match && match.trace_id) || mintTrace(gdev),
    traced: Boolean(match && clean(match.trace_id)),
    origin: 'beacon',
    source: 'grafana-labels',
  }}];
}

// 1b. direct POST wins if it names a device and a fault
if (clean(posted.device) && clean(posted.fault)) {
  return [{ json: {
    device: clean(posted.device),
    fault: clean(posted.fault),
    interface: clean(posted.interface),
    detail: clean(posted.detail),
    peer: clean(posted.peer),
    trace_id: clean(posted.trace_id) || mintTrace(clean(posted.device)),
    origin: 'posted',
    source: 'posted',
  }}];
}

// 2. otherwise take what Elasticsearch has seen recently
const hits = (es.hits && es.hits.hits) || [];
const seen = new Set();
const out = [];
for (const h of hits) {
  const d = h._source.data || {};
  if (!clean(d.device) || !clean(d.fault)) continue;
  const key = d.device + '|' + d.fault + '|' + (d.interface || '');
  if (seen.has(key)) continue;
  seen.add(key);
  out.push({ json: {
    device: clean(d.device),
    fault: clean(d.fault),
    interface: clean(d.interface),
    detail: clean(d.detail),
    peer: clean(d.peer),
    // The beacon's id. Falling back to a minted one would silently break
    // correlation, so an event without one is marked rather than hidden.
    trace_id: clean(d.trace_id) || mintTrace(clean(d.device)),
    traced: Boolean(clean(d.trace_id)),
    origin: 'beacon',
    source: 'elasticsearch',
  }});
}
if (out.length === 0) {
  return [{ json: {
    device: '', fault: 'no_fault_found', interface: '', trace_id: '',
    detail: 'alert fired but no fault event was found in the last 2 minutes',
    origin: 'none', source: 'none',
  }}];
}
return out;

// FAIL CLOSED. The LLM's answer is only ever a NAME, and only a name
// from this list is allowed through. Anything else — a hallucinated
// template, prose, malformed JSON — stops here and never reaches
// salt-api, let alone a router.
//
// Worth being precise about what this does and does not buy. The
// whitelist makes an *invented* runbook impossible. It does nothing
// about a real runbook chosen for the wrong fault. What contains that is
// on the other side: every template is two to four lines, idempotent,
// and takes its parameters from pillar rather than from this payload, so
// the worst a wrong-but-allowed choice can do is a no-op.
const ALLOWED = ['restore_interface', 'fix_p2p_mtu', 'sync_from_netbox',
                 'sync_from_pillar', 'restore_bgp_neighbor',
                 // The two config-management states. Both are idempotent
                 // convergences to a declared source of truth rather than
                 // edits, so the worst a wrong choice does is re-assert
                 // what NetBox or the fabric plan already says.
                 'golden_config', 'bgp_policy'];

const fault = $('Normalize alert').item.json;
const MAX_PER_HOUR = 3;
const MODEL = $env.OLLAMA_MODEL || 'llama3.1';
const ACTOR = 'n8n/' + MODEL;

// .item pairs by index and silently fails here — the breaker node emits a
// single response while this node runs per LLM item, so read its first
// output explicitly.
let recent = 0, alreadyDecided = 0;
try {
  const b = $('Circuit breaker: recent count').first().json;
  recent = b.aggregations.changes.doc_count || 0;
  alreadyDecided = (b.aggregations.settled.doc_count || 0)
                 + (b.aggregations.deciding.doc_count || 0);
} catch (e) {
  // FAIL CLOSED, and it did not used to. A 401 after a password rotation,
  // a 503, a shard failure -- with neverError the response arrived as a
  // normal item with no aggregations, this catch set recent = -1, and
  // -1 >= MAX_PER_HOUR is false, so execution carried on to the model and
  // to salt-api with no rate limit and no duplicate check. The node's own
  // header says FAIL CLOSED. Now it does.
  const reason = 'circuit breaker could not be read: ' + (e && e.message ? e.message : e);
  return [{ json: Object.assign({}, fault, {
    accepted: false, chosen: null, reason: '', recent: -1,
    raw: reason,
    note: 'breaker unreadable — refusing to decide',
    auditBody: audit('decision.blocked', 'blocked', null, reason),
  })}];
}

// One audit record per decision, written before anything is applied, so a
// decision that is about to fail is still on the record. Fields match the
// strict mapping on the napalm-audit data stream; anything else goes in
// detail, which is stored but not indexed.
function audit(action, outcome, state, reason, extra) {
  return JSON.stringify({
    '@timestamp': new Date().toISOString(),
    action: action,
    outcome: outcome,
    trace_id: fault.trace_id || '',
    actor: ACTOR,
    actor_type: 'model',
    source: 'n8n',
    device: fault.device || '',
    fault: fault.fault || '',
    interface: fault.interface || '',
    state: state || '',
    reason: (reason || '').slice(0, 1000),
    detail: Object.assign({
      execution_id: $execution.id,
      workflow: $workflow.name,
      model: MODEL,
      recent_changes_1h: recent,
      fault_origin: fault.origin,
    }, extra || {}),
  });
}

// Someone already decided this one. Stopping here is what keeps two
// Grafana notifications for one outage from becoming two concurrent
// state.apply runs against the same router.
if (alreadyDecided > 0) {
  const reason = 'trace ' + fault.trace_id +
                 ' is already settled or being decided right now';
  return [{ json: Object.assign({}, fault, {
    accepted: false, chosen: null, reason: '', recent: recent,
    raw: reason,
    note: 'duplicate — this fault is already being handled',
    auditBody: audit('decision.duplicate', 'skipped', null, reason),
  })}];
}

if (recent >= MAX_PER_HOUR) {
  const reason = 'circuit breaker: ' + recent + ' changes to ' + fault.device +
                 ' in the last hour';
  return [{ json: Object.assign({}, fault, {
    accepted: false, chosen: null, reason: '', recent: recent,
    raw: reason,
    note: 'circuit breaker open — escalated to a human',
    auditBody: audit('decision.blocked', 'blocked', null, reason),
  })}];
}

const raw = ($json.response || '').trim();

let chosen = null, reason = '';
try {
  const m = raw.match(/\{[\s\S]*\}/);
  if (m) {
    const parsed = JSON.parse(m[0]);
    chosen = parsed.state;
    reason = parsed.reason || '';
  }
} catch (e) { /* fall through to rejection below */ }

// 'none' is a first-class answer: the LLM declining to act is a success,
// not a failure. It routes to the rejected index for a human.
if (chosen === 'none' || !ALLOWED.includes(chosen)) {
  const declined = chosen === 'none';
  return [{ json: Object.assign({}, fault, {
    accepted: false,
    chosen: chosen,
    reason: reason,
    raw: raw.slice(0, 400),
    note: declined ? 'LLM declined: no template addresses this fault'
                   : 'rejected: not in whitelist',
    auditBody: audit(declined ? 'decision.declined' : 'decision.rejected',
                     declined ? 'declined' : 'rejected',
                     chosen, reason, { llm_raw: raw.slice(0, 1000) }),
  })}];
}

// The trace id and the actor travel with the call. Salt puts both into the
// commit message on the device, so `info from state /system configuration checkpoint *`
// on the router names the decision that changed it.
// No credentials in here. Whatever this node returns becomes an ITEM, and
// n8n persists items to its execution store -- SAVE_ON_SUCCESS=all with
// MAX_AGE 365 days -- so a password placed here is a password in a sqlite
// file for a year, readable by anyone with the n8n UI or a copy of the
// n8n-data volume, and it is not covered by N8N_ENCRYPTION_KEY (that
// protects credential objects, not execution data).
//
// The salt-api node adds username/password/eauth from $env at request
// time instead, where the value is resolved and sent but never stored.
const saltPayload = JSON.stringify({
  client: 'local',
  tgt: fault.device,
  fun: 'state.apply',
  arg: [chosen],
  kwarg: { pillar: {
    interface: fault.interface,
    peer: fault.peer || '',
    trace_id: fault.trace_id || '',
    actor: ACTOR,
    actor_type: 'model',
  }},
});

return [{ json: Object.assign({}, fault, {
  accepted: true, chosen: chosen, reason: reason, recent: recent,
  actor: ACTOR, saltPayload: saltPayload,
  auditBody: audit('decision.made', 'accepted', chosen, reason,
                   { llm_raw: raw.slice(0, 1000) }),
})}];

const f = $('Validate against whitelist').item.json;
const salt = $json;

// Did the state actually do anything? salt-api answers 200 even when the
// state failed or was blocked by the change gate, so the outcome has to be
// read out of the return rather than inferred from the HTTP status.
let applied = false, blocked = false, saltComment = '';
try {
  const ret = salt.return[0][f.device];
  const states = Object.values(ret);
  applied = states.some(s => s.result === true && s.changes &&
                             Object.keys(s.changes).length > 0);
  blocked = states.some(s => s.result === false &&
                             String(s.comment || '').startsWith('blocked:'));
  saltComment = states.map(s => s.comment).filter(Boolean).join(' | ').slice(0, 1000);
} catch (e) {
  saltComment = 'could not parse the salt-api response';
}

const doc = {
  device: f.device,
  fault: f.fault,
  interface: f.interface,
  detail: f.detail,
  trace_id: f.trace_id,
  chosen_state: f.chosen,
  llm_reason: f.reason,
  recent_remediations: f.recent,
  applied: applied,
  blocked: blocked,
  salt_comment: saltComment,
  salt_result: JSON.stringify(salt).slice(0, 4000),
  stamp: new Date().toISOString(),
};

// The change itself is audited by Salt, inside the state, with the config
// diff attached — see _states/audited.py. What n8n records here is the
// other half: that it asked, and what came back. If Salt has a
// change.applied for this trace and n8n has no change.requested, or the
// reverse, something between the two is lying.
const auditBody = JSON.stringify({
  '@timestamp': new Date().toISOString(),
  action: 'change.requested',
  outcome: blocked ? 'blocked' : (applied ? 'success' : 'no-change'),
  trace_id: f.trace_id || '',
  actor: f.actor || 'n8n',
  actor_type: 'workflow',
  source: 'n8n',
  device: f.device || '',
  fault: f.fault || '',
  interface: f.interface || '',
  state: f.chosen || '',
  reason: saltComment,
  detail: {
    execution_id: $execution.id,
    workflow: $workflow.name,
    salt_result: JSON.stringify(salt).slice(0, 4000),
  },
});

return [{ json: { esBody: JSON.stringify(doc), auditBody: auditBody } }];

const f = $json;
const doc = {
  trace_id: f.trace_id,
  device: f.device,
  fault: f.fault,
  interface: f.interface,
  rejected_choice: f.chosen,
  raw: f.raw,
  note: f.note,
  recent_remediations: f.recent,
  stamp: new Date().toISOString(),
};
return [{ json: { esBody: JSON.stringify(doc) } }];

// One query, two questions, because both answers live in the same
// append-only audit stream:
//
//   changes    — how many times has this DEVICE actually been changed in
//                the last hour? This is the circuit breaker. It counts
//                change.applied, which only Salt writes, and only after a
//                diff really landed on a router. The previous version
//                counted rows in napalm-remediations, an index this
//                workflow writes itself, so it was measuring its own
//                output rather than what reached a device.
//
//   this_trace — has a decision already been made for THIS fault? Grafana
//                re-notifies on its repeat interval and Elasticsearch can
//                return the same fault twice, so one outage produced two
//                executions, two LLM calls and two concurrent state.apply
//                runs against one device. Salt refuses the second, so the
//                collision was harmless and invisible; with a trace id it
//                is neither.
//
// The authoritative rate limit is still Salt's: audit.change_allowed()
// runs inside the state, so it also covers the reactor's drift path, which
// this workflow never sees. Checking here as well means not waking the
// model for a device already known to be flapping.
const f = $json;
const q = {
  size: 0,
  track_total_hits: true,
  query: { bool: { filter: [
    { term: { device: f.device } },
    { range: { '@timestamp': { gte: 'now-1h' } } },
  ]}},
  aggs: {
    // Unattended changes only, matching audit.change_allowed(). A
    // person provisioning a router is not the automation looping,
    // and counting their changes here meant the model was refused
    // for an hour after any planned work -- on exactly the device
    // most likely to need it. Two implementations of one control
    // had drifted apart; this is the second one.
    changes: { filter: { bool: {
      filter: [{ term: { action: 'change.applied' } }],
      must_not: [{ term: { actor_type: 'human' } }],
    } } },
    // Two different questions about this trace, because "a decision was
    // made" and "the fault was dealt with" are not the same thing.
    //
    // settled  — a change actually reached the device. Nothing more to do.
    //
    // deciding — a decision was made in the last two minutes. That is a
    //            concurrency guard against two Grafana notifications for
    //            one outage, not a permanent record.
    //
    // Counting any past decision.made as "handled" meant a remediation
    // refused by the rate limit or the blast radius was never retried, even
    // after the ceiling cleared. The change had not happened and the system
    // considered the fault closed -- a stuck fault that nothing would ever
    // pick up again.
    settled: { filter: { bool: { filter: [
      { term: { trace_id: f.trace_id || '__none__' } },
      { terms: { action: ['change.applied', 'change.verified'] } },
    ]}}},
    deciding: { filter: { bool: { filter: [
      { term: { trace_id: f.trace_id || '__none__' } },
      { term: { action: 'decision.made' } },
      { range: { '@timestamp': { gte: 'now-2m' } } },
    ]}}},
  },
};
return [{ json: Object.assign({}, f, { breakerQuery: JSON.stringify(q) }) }];
